/** static void VBlankCB_LinkBattleSave(void) */
export function VBlankCB_LinkBattleSave(): any {
  TransferPlttBuffer();
}

/** static bool32 InitSaveWindowAfterLinkBattle(u8 *state) */
export function InitSaveWindowAfterLinkBattle(state: any): any {
  switch (state)
      {
      case 0:
          SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0);
          SetVBlankCallback(NULL);
          ScanlineEffect_Stop();
          DmaClear16(3, PLTT, PLTT_SIZE);
          DmaFillLarge16(3, 0, VRAM, VRAM_SIZE, 0x1000);
          break;
      case 1:
          ResetSpriteData();
          ResetTasks();
          ResetPaletteFade();
          ScanlineEffect_Clear();
          break;
      case 2:
          ResetBgsAndClearDma3BusyFlags(0);
          InitBgsFromTemplates(0, sBgTemplates_LinkBattleSave, ARRAY_COUNT(sBgTemplates_LinkBattleSave));
          InitWindows(sWindowTemplates_LinkBattleSave);
          LoadUserWindowBorderGfx_(0, 8, BG_PLTT_ID(14));
          Menu_LoadStdPalAt(BG_PLTT_ID(15));
          break;
      case 3:
          ShowBg(0);
          BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
          SetVBlankCallback(VBlankCB_LinkBattleSave);
          EnableInterrupts(1);
          break;
      case 4:
          return TRUE;
      }

      state++;
      return FALSE;
}

/** void CB2_SetUpSaveAfterLinkBattle(void) */
export function CB2_SetUpSaveAfterLinkBattle(): any {
  if (InitSaveWindowAfterLinkBattle(gMain.state))
      {
          CreateTask(Task_SaveAfterLinkBattle, 0x50);
          SetMainCallback2(CB2_SaveAfterLinkBattle);
      }
}

/** static void CB2_SaveAfterLinkBattle(void) */
export function CB2_SaveAfterLinkBattle(): any {
  RunTasks();
      UpdatePaletteFade();
}

/** static void Task_SaveAfterLinkBattle(u8 taskId) */
export function Task_SaveAfterLinkBattle(taskId: any): any {
  let state: any = gTasks[taskId].data;

      if (!gPaletteFade.active)
      {
          switch (state)
          {
          case 0:
              FillWindowPixelBuffer(0, PIXEL_FILL(1));
              AddTextPrinterParameterized2(0,
                                          FONT_NORMAL,
                                          gText_SavingDontTurnOffPower,
                                          TEXT_SKIP_DRAW,
                                          NULL,
                                          TEXT_COLOR_DARK_GRAY,
                                          TEXT_COLOR_WHITE,
                                          TEXT_COLOR_LIGHT_GRAY);
              DrawTextBorderOuter(0, 8, 14);
              PutWindowTilemap(0);
              CopyWindowToVram(0, COPYWIN_FULL);
              BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);

              if (gWirelessCommType != 0 && InUnionRoom())
              {
                  if (Link_AnyPartnersPlayingFRLG_JP())
                  {
                      state = 1;
                  }
                  else
                  {
                      state = 5;
                  }
              }
              else
              {
                  gSoftResetDisabled = TRUE;
                  state = 1;
              }
              break;
          case 1:
              SetContinueGameWarpStatusToDynamicWarp();
              WriteSaveBlock2();
              state = 2;
              break;
          case 2:
              if (WriteSaveBlock1Sector())
              {
                  ClearContinueGameWarpStatus2();
                  state = 3;
                  gSoftResetDisabled = FALSE;
              }
              break;
          case 3:
              BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
              state = 4;
              break;
          case 4:
              FreeAllWindowBuffers();
              SetMainCallback2(gMain.savedCallback);
              DestroyTask(taskId);
              break;
          case 5:
              CreateTask(Task_LinkFullSave, 5);
              state = 6;
              break;
          case 6:
              if (!FuncIsActiveTask(Task_LinkFullSave))
              {
                  state = 3;
              }
              break;
          }
      }
}

/** static void ShowSaveInfoWindow(void) */
export function ShowSaveInfoWindow(): any {
  let saveInfoWindow: any = sSaveInfoWindowTemplate;
      let gender: any = null;
      let color: any = null;
      let xOffset: any = null;
      let yOffset: any = null;

      if (!FlagGet(FLAG_SYS_POKEDEX_GET))
      {
          saveInfoWindow.height -= 2;
      }

      sSaveInfoWindowId = AddWindow(saveInfoWindow);
      DrawStdWindowFrame(sSaveInfoWindowId, FALSE);

      gender = gSaveBlock2Ptr.playerGender;
      color = TEXT_COLOR_RED;   

      if (gender == MALE)
      {
          color = TEXT_COLOR_BLUE;
      }

       
      yOffset = 1;
      BufferSaveMenuText(SAVE_MENU_LOCATION, gStringVar4, TEXT_COLOR_GREEN);
      AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gStringVar4, 0, yOffset, TEXT_SKIP_DRAW, NULL);

       
      yOffset += 16;
      AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gText_SavingPlayer, 0, yOffset, TEXT_SKIP_DRAW, NULL);
      BufferSaveMenuText(SAVE_MENU_NAME, gStringVar4, color);
      xOffset = GetStringRightAlignXOffset(FONT_NORMAL, gStringVar4, 0x70);
      PrintPlayerNameOnWindow(sSaveInfoWindowId, gStringVar4, xOffset, yOffset);

       
      yOffset += 16;
      AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gText_SavingBadges, 0, yOffset, TEXT_SKIP_DRAW, NULL);
      BufferSaveMenuText(SAVE_MENU_BADGES, gStringVar4, color);
      xOffset = GetStringRightAlignXOffset(FONT_NORMAL, gStringVar4, 0x70);
      AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gStringVar4, xOffset, yOffset, TEXT_SKIP_DRAW, NULL);

      if (FlagGet(FLAG_SYS_POKEDEX_GET) == TRUE)
      {
           
          yOffset += 16;
          AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gText_SavingPokedex, 0, yOffset, TEXT_SKIP_DRAW, NULL);
          BufferSaveMenuText(SAVE_MENU_CAUGHT, gStringVar4, color);
          xOffset = GetStringRightAlignXOffset(FONT_NORMAL, gStringVar4, 0x70);
          AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gStringVar4, xOffset, yOffset, TEXT_SKIP_DRAW, NULL);
      }

       
      yOffset += 16;
      AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gText_SavingTime, 0, yOffset, TEXT_SKIP_DRAW, NULL);
      BufferSaveMenuText(SAVE_MENU_PLAY_TIME, gStringVar4, color);
      xOffset = GetStringRightAlignXOffset(FONT_NORMAL, gStringVar4, 0x70);
      AddTextPrinterParameterized(sSaveInfoWindowId, FONT_NORMAL, gStringVar4, xOffset, yOffset, TEXT_SKIP_DRAW, NULL);

      CopyWindowToVram(sSaveInfoWindowId, COPYWIN_GFX);
}

